/* Veal, Pituitary Diseases 2026. All 29 supplied objectives in order.
 * Brief labeled guideline updates clarify current testing and treatment without expanding scope.
 */
(function(){
  "use strict";
  function q(prompt,answer,wrong,explanation){return {prompt:prompt,choices:[answer].concat(wrong),correct:0,explanation:explanation};}
  function u(title,html,coverage,test,apply){return {title:title,html:html,coverage:coverage,test:test,apply:apply};}
  function c(title,html,coverage,tp,ta,tw,ap,aa,aw){return u(title,html,coverage,[q(tp,ta,tw,ta)],[q(ap,aa,aw,aa)]);}
  function s(id,title,description,units){var r={id:id,title:title,description:description,cards:[],test:[],apply:[]};units.forEach(function(x,i){r.cards.push({title:x.title,html:x.html,coverage:x.coverage});["test","apply"].forEach(function(m){x[m].forEach(function(z){z.card=i;r[m].push(z);});});});return r;}
  function ref(url,label){return '<a href="'+url+'" target="_blank" rel="noopener noreferrer">'+label+'</a>';}
  var hypo=ref('https://www.endocrine.org/clinical-practice-guidelines/hormone-replacement-in-hypopituitarism','Endocrine Society: hypopituitarism');
  var gh=ref('https://www.endocrine.org/clinical-practice-guidelines/adult-growth-hormone-deficiency','Endocrine Society: adult GH deficiency');
  var inc=ref('https://support.endocrine.org/clinical-practice-guidelines/pituitary-incidentaloma','Endocrine Society: pituitary incidentaloma');
  var di=ref('https://academic.oup.com/jcem/article/107/10/2701/6623615','JCEM: central diabetes insipidus');
  window.PITUITARY_DISEASES_OBJECTIVES=[
    s('01-anatomy-axes','1. Hypothalamic–pituitary anatomy, physiology, and target-organ axes','Objective 1. Slides 2–20.',[
      c('Anatomy and communication','<p>The hypothalamus lies above the pea-sized pituitary. Releasing/inhibiting hormones reach the <strong>anterior pituitary through portal blood</strong>; hypothalamic axons carry ADH and oxytocin to the <strong>posterior pituitary</strong> for release.</p>',['anatomy-hypothalamus-pituitary','anterior-portal','posterior-axons'],'How do hypothalamic hormones reach the anterior pituitary?','Through pituitary portal circulation',['Through the bile duct','Only through CSF','Through the thyroid artery'],'A stalk injury causes polyuria and loss of ADH release. Which route was disrupted?','Hypothalamic axons to the posterior pituitary',['Anterior portal blood only','Hepatic portal blood','Adrenal medulla nerves']),
      c('HPA axis','<p><strong>CRH → ACTH → adrenal cortisol.</strong> Cortisol feeds back to suppress CRH and ACTH.</p>',['hpa-crh-acth-cortisol','hpa-feedback'],'Which sequence is the HPA axis?','CRH → ACTH → cortisol',['TRH → TSH → cortisol','GnRH → LH → T4','GHRH → GH → aldosterone'],'Low ACTH and low cortisol localize dysfunction to which level?','Pituitary or hypothalamic level',['Primary adrenal cortisol excess','Primary thyroid disease','Posterior pituitary only']),
      c('HPT axis','<p><strong>TRH → TSH → thyroid T4/T3.</strong> Thyroid hormones provide negative feedback to hypothalamus and pituitary.</p>',['hpt-trh-tsh-thyroid','hpt-feedback'],'Which pituitary hormone drives thyroid T4/T3 production?','TSH',['ACTH','ADH','GH'],'Low free T4 with an inappropriately normal TSH suggests what?','Central hypothyroidism',['Primary hyperthyroidism','Primary hyperparathyroidism','Central DI']),
      c('HPG axis','<p><strong>GnRH → LH/FSH → gonadal sex steroids and gametogenesis.</strong> Sex steroids provide negative feedback.</p>',['hpg-gnrh-lh-fsh','hpg-targets-feedback'],'Which hypothalamic hormone stimulates LH and FSH?','GnRH',['CRH','TRH','Somatostatin'],'Low testosterone with low-normal LH points to what level?','Hypothalamic–pituitary hypogonadism',['Primary testicular failure','Thyroid C cells','Adrenal medulla']),
      c('Growth, prolactin, and posterior pathways','<p><strong>GHRH → GH → IGF-1</strong> (mainly liver); somatostatin inhibits GH. Dopamine tonically inhibits prolactin. ADH increases renal water reabsorption; oxytocin supports uterine contraction and milk letdown.</p>',['ghrh-gh-igf1','somatostatin-inhibits-gh','dopamine-inhibits-prl','adh-kidney','oxytocin'],'What normally inhibits prolactin secretion?','Dopamine',['ACTH','Oxytocin','Aldosterone'],'A drug blocks dopamine receptors and prolactin rises. What explains this?','Loss of tonic prolactin inhibition',['Excess ADH action','Loss of cortisol feedback','Direct thyroid destruction'])
    ]),
    s('02-function-levels','2. Hypofunction, hyperfunction, and endocrine levels','Objective 2. Slides 21–22.',[
      c('Hypofunction versus hyperfunction','<p><strong>Hypofunction</strong> means insufficient hormone secretion; <strong>hyperfunction</strong> means excess secretion. Interpret the pituitary hormone with its target hormone rather than alone.</p>',['hypofunction','hyperfunction','paired-hormones'],'What is endocrine hyperfunction?','Excess hormone secretion',['Insufficient secretion','Normal feedback','Target resistance only'],'High IGF-1 with unsuppressed GH represents what?','Hyperfunction of the GH axis',['GH hypofunction','Primary thyroid failure','ADH deficiency']),
      c('Primary, secondary, tertiary','<p><strong>Primary</strong> disease begins in the target gland, <strong>secondary</strong> in the pituitary, and <strong>tertiary</strong> in the hypothalamus. Feedback patterns help localize the problem.</p>',['primary-target','secondary-pituitary','tertiary-hypothalamus'],'Where does secondary endocrine disease originate?','Pituitary',['Target gland','Hypothalamus','Kidney only'],'Low T4 and low/inappropriately normal TSH localize to which category?','Secondary/central disease',['Primary thyroid failure','Primary cortisol excess','Nephrogenic DI'])
    ]),
    s('03-mechanisms','3. Mechanisms and etiologies of pituitary disease','Objective 3. Slides 23, 26–27.',[
      c('Deficiency mechanisms','<p>Deficiency can result from adenoma or other mass compression, surgery/radiation, infarction (including Sheehan syndrome), trauma, infection, autoimmune/inflammatory or infiltrative disease, and genetic defects.</p>',['deficiency-mass','deficiency-treatment','deficiency-infarct-trauma','deficiency-infection-infiltrative-genetic'],'Which mechanism commonly causes several pituitary deficiencies together?','Compression by a sellar mass',['Isolated kidney resistance','Thyroid hormone excess only','Normal negative feedback'],'Postpartum hemorrhage is followed by failure to lactate and amenorrhea. Which mechanism fits?','Pituitary infarction (Sheehan syndrome)',['PTH resistance','Nephrogenic DI','Primary Graves disease']),
      c('Excess and resistance','<p>Hormone excess most often comes from a functioning benign adenoma; exogenous hormone or activating mutations can mimic it. Hormone resistance reflects receptor/signaling defects, such as GH-receptor resistance in Laron syndrome or renal ADH resistance.</p>',['excess-adenoma','excess-exogenous-mutation','resistance-receptor-signaling'],'What is the usual pituitary mechanism of autonomous hormone excess?','A functioning adenoma',['Portal-vein thrombosis in every case','Loss of all receptors','Primary kidney failure'],'High hormone levels with poor target response suggest which mechanism?','Hormone resistance',['Simple hormone deficiency','Normal physiology','Target-gland hyperfunction'])
    ]),
    s('04-hypopituitarism','4. Hypopituitarism and its etiologies','Objective 4. Slides 24–28.',[
      c('Definition and biochemical pattern','<p>Hypopituitarism is inadequate production of one or more anterior pituitary hormones from pituitary or hypothalamic disease. The key pattern is a <strong>low target hormone with a low or inappropriately normal pituitary hormone</strong>.</p>',['hypopit-definition','hypopit-pattern'],'Which pattern supports hypopituitarism?','Low target hormone with low/inappropriately normal pituitary hormone',['Low target hormone with markedly high trophic hormone','High target and high trophic hormones always','Normal paired hormones'],'Free T4 is low and TSH is normal. Why is normal TSH abnormal here?','It is inappropriately normal for the low target hormone',['It proves normal thyroid function','It proves primary hyperthyroidism','It diagnoses DI']),
      c('Presentation and causes','<p>Presentation depends on which axes fail: growth failure/delayed puberty in children, fatigue, pallor/fine skin and reproductive symptoms in adults, or mass effects. Causes include sellar masses, surgery/radiation, infiltration/infection, infarction, trauma and genetics.</p>',['hypopit-variable-presentation','hypopit-child-growth-puberty','hypopit-adult','hypopit-etiologies'],'Why can two patients with hypopituitarism look different?','Different axes and degrees of loss produce different findings',['Every hormone has the same effect','Only age matters','Hypopituitarism affects ADH alone'],'A patient has fatigue, amenorrhea and visual-field loss. What unifying cause needs evaluation?','A sellar mass causing hormone loss and compression',['Isolated primary ovarian failure only','Simple dehydration','Primary hyperparathyroidism'])
    ]),
    s('05-growth-hormone-effects','5. Overall effects of growth hormone','Objective 5. Slides 29–32.',[
      c('Growth and body composition','<p>GH, largely through IGF-1, drives epiphyseal cartilage and linear growth in children. In adults it supports bone turnover, lean mass and protein synthesis while promoting lipolysis.</p>',['gh-linear-growth','gh-igf1','gh-bone-muscle','gh-lipolysis'],'What mediates many GH effects?','IGF-1',['PTHrP','Calcitonin','Aldosterone'],'A child lacks GH before epiphyseal closure. Which process is most affected?','Linear growth',['Urine concentration only','Thyroid iodine uptake only','Calcium clotting only']),
      c('Metabolic and systemic effects','<p>GH opposes insulin in some tissues, promotes hepatic glucose output, and influences lipids, cardiac function, mood/cognition and immune activity. These effects explain hypoglycemia in deficient infants and glucose intolerance in excess.</p>',['gh-anti-insulin','gh-gluconeogenesis','gh-systemic'],'Which metabolic action fits GH?','Raises hepatic glucose output and opposes insulin action',['Always lowers glucose by increasing insulin sensitivity','Blocks IGF-1 production','Only controls water balance'],'Why can severe congenital GH deficiency cause hypoglycemia?','Loss of GH counter-regulatory action',['Excess aldosterone','Excess thyroid hormone','Increased renal glucose loss in every case'])
    ]),
    s('06-gh-deficiency-manifestations','6. Clinical manifestations of GH deficiency by age and onset','Objective 6. Slides 33–35, 43–44.',[
      c('Congenital GH deficiency','<p>Newborn clues include hypoglycemia and prolonged jaundice; reduced growth velocity becomes clear during infancy. Body proportions are generally preserved.</p>',['ghd-congenital-hypoglycemia-jaundice','ghd-congenital-growth'],'Which neonatal findings suggest congenital GH deficiency?','Hypoglycemia and jaundice followed by poor growth',['Tall stature and hyperglycemia','Polyuria with high sodium only','Macrognathia and large hands'],'An infant has recurrent hypoglycemia and slowing length velocity. Which axis should be assessed?','GH–IGF-1 axis',['PTHrP axis','Renin only','Calcitonin only']),
      c('Acquired childhood deficiency','<p>Acquired childhood GHD causes decreased height velocity, delayed bone age and relatively preserved/increased weight. Consider tumor, cranial radiation or head trauma.</p>',['ghd-child-growth-failure','ghd-child-delayed-bone-age','ghd-child-weight','ghd-child-causes'],'Which pattern fits acquired childhood GHD?','Poor height velocity, delayed bone age, relatively increased weight',['Rapid linear overgrowth','Advanced bone age in every case','Severe wasting with normal growth'],'A previously growing child slows after cranial irradiation. What is the key concern?','Acquired GH deficiency',['Gigantism','Primary aldosteronism','Calcitonin excess']),
      c('Adult GH deficiency','<p>Adults may have central adiposity, reduced lean mass/energy, dyslipidemia, low mood or concentration, reduced exercise capacity, and low bone density/fracture risk. Symptoms are nonspecific, so test only with a credible pituitary context.</p>',['ghd-adult-body-composition','ghd-adult-energy-mood','ghd-adult-lipid-cardiac','ghd-adult-bone'],'Which is typical of adult GHD?','Central adiposity with reduced lean mass and energy',['Accelerated height growth','Exophthalmos','Hyperpigmentation from high ACTH'],'An adult with prior pituitary surgery has central adiposity, low bone density and low energy. Which deficiency fits?','GH deficiency',['ADH excess','PTH excess','Calcitonin deficiency'])
    ]),
    s('07-pediatric-gh-assessment','7. Pediatric GH-deficiency assessment and additional workup','Objective 7. Slides 36–39.',[
      c('Growth data, bone age, and IGF-1','<p>Start with serial height/growth velocity, growth chart and hand/wrist bone age. IGF-1 is stable across the day, unlike pulsatile GH, but can also be low with malnutrition, hypothyroidism, diabetes, renal/hepatic disease or GH resistance.</p>',['child-growth-velocity','child-bone-age','igf1-stable','igf1-nonspecific','random-gh-poor'],'Why is a random GH level unreliable?','GH secretion is pulsatile',['GH never enters blood','IGF-1 is pulsatile only','GH is stored in bone'],'A short child has low IGF-1. What must happen before labeling GHD?','Assess growth pattern and exclude other causes of low IGF-1',['Diagnose from IGF-1 alone','Start thyroid ablation','Order PTHrP only']),
      c('Stimulation, MRI, and other axes','<p>When needed, specialist GH stimulation testing evaluates reserve; cutoff depends on assay/protocol. Obtain pituitary MRI for structural disease and evaluate/correct other pituitary deficits when insufficiency is found.</p>',['child-gh-stimulation','child-assay-cutoff','child-mri','child-other-axes'],'What follows confirmed/suspected pituitary GHD?','Pituitary imaging and assessment of other axes',['No further evaluation','Thyroidectomy','Only urine calcium'],'A child fails GH stimulation and has headaches. What is the next focused study?','Pituitary MRI',['RAIU scan','Colonoscopy','Adrenal biopsy'])
    ]),
    s('08-laron-syndrome','8. Laron syndrome mechanism and phenotype','Objective 8. Slides 40–42.',[
      c('GH receptor resistance','<p>Laron syndrome is usually autosomal recessive <strong>GH-receptor resistance</strong>: GH is present/high but IGF-1 is very low. Findings include severe proportionate short stature, prominent forehead, depressed nasal bridge, small jaw, central obesity and hypoglycemia. Recombinant IGF-1 bypasses the receptor defect.</p>',['laron-gh-receptor','laron-high-gh-low-igf1','laron-phenotype','laron-hypoglycemia','laron-igf1-treatment'],'Which laboratory mechanism fits Laron syndrome?','High/present GH with very low IGF-1 from receptor resistance',['Low GH from pituitary destruction','High IGF-1 from GH excess','Low ADH from stalk injury'],'A short child has high GH, very low IGF-1 and characteristic facies. What treatment bypasses the defect?','Recombinant IGF-1',['More GH alone','Desmopressin','Cabergoline'])
    ]),
    s('09-adult-gh-risk-pattern','9. Adult GH-deficiency risk factors and diagnostic pattern','Objective 9. Slides 43–46.',[
      c('Who warrants evaluation?','<p>Evaluate adults with pituitary/hypothalamic lesions, surgery, cranial irradiation, childhood GHD needing retesting, or multiple pituitary deficiencies. Do not screen nonspecific fatigue without this context.</p>',['adult-ghd-risks','adult-ghd-no-general-screen'],'Who most warrants adult GHD testing?','A patient with pituitary surgery and other pituitary deficits',['Any tired adult with no pituitary history','Every healthy older adult','Anyone with isolated hypertension'],'An adult has fatigue but no structural, treatment or hormonal risk factors. What is appropriate?','Do not diagnose GHD from symptoms alone',['Start GH immediately','Use random GH as definitive','Order thyroidectomy']),
      c('Pattern suggesting severe deficiency','<p>Low age-adjusted IGF-1 supports GHD but is not diagnostic by itself. With structural disease and <strong>three or more other pituitary deficiencies</strong>, a low IGF-1 may make stimulation testing unnecessary; otherwise confirmation is usually required. '+gh+'</p>',['adult-low-igf1','adult-multiple-deficits','adult-stimulation-usual'],'When can adult GHD sometimes be diagnosed without stimulation testing?','Strong structural context, multiple other pituitary deficits, and low IGF-1',['Any single low random GH','Any fatigue plus obesity','High IGF-1 alone'],'A patient has one possible deficit and borderline IGF-1. What is usually needed?','Validated stimulation testing',['No confirmation','Water deprivation','RAIU scan'])
    ]),
    s('10-gh-diagnostic-tests','10. GH-deficiency tests and contraindications','Objective 10. Slides 46–47.',[
      c('Insulin tolerance test','<p>Insulin-induced hypoglycemia should provoke GH (and cortisol). Failure supports GHD. It requires close supervision and is contraindicated in seizure disorder and significant ischemic heart/cerebrovascular disease; use caution/alternatives in older adults.</p>',['itt-mechanism','itt-gold-standard-context','itt-contra-seizure-cardiovascular'],'What does the insulin tolerance test assess?','GH response to induced hypoglycemia',['ADH response to water loading','Prolactin after dopamine','TSH after iodine'],'A patient with epilepsy needs GHD confirmation. Which test should be avoided?','Insulin tolerance test',['Age-adjusted IGF-1','Pituitary MRI','Alternative stimulation testing']),
      c('Glucagon and interpretation','<p>Glucagon stimulation is an alternative when insulin testing is unsafe. Serial GH sampling is required; diagnostic thresholds vary with assay, BMI and protocol, so specialists interpret results.</p>',['glucagon-stimulation','serial-gh','test-threshold-context'],'Why are serial samples collected during stimulation testing?','The stimulated GH peak, not one random value, determines reserve',['GH never changes','Only sodium matters','To diagnose hypercalcemia'],'A cardiac patient needs dynamic GHD testing. Which safer alternative is commonly considered?','Glucagon stimulation test',['Induce severe hypoglycemia anyway','Desmopressin challenge','Cosyntropin only'])
    ]),
    s('11-gh-treatment','11. Treatment of GH deficiency','Objective 11. Slides 42, 48.',[
      c('Replacement by age and cause','<p>Children with true GHD receive daily subcutaneous recombinant GH until growth completion; GH-receptor resistance uses recombinant IGF-1. Adults with proven GHD may receive individualized daily GH titrated to age-adjusted IGF-1 and symptoms. Watch edema, arthralgia, paresthesia/carpal tunnel and glucose effects. '+hypo+'</p>',['child-rhgh','laron-rhigf1','adult-individual-gh','gh-monitor-igf1','gh-adverse-fluid-joint-glucose'],'What treats pituitary GH deficiency in a growing child?','Recombinant GH',['Cabergoline','Desmopressin','Hydrochlorothiazide'],'An adult on GH develops edema and carpal-tunnel symptoms. What should be considered?','Dose-related GH adverse effects and dose reduction',['Permanent DI','Primary adrenal crisis','PTH resistance'])
    ]),
    s('12-acth-deficiency','12. ACTH deficiency: presentation, diagnosis, and treatment','Objective 12. Slides 51–61.',[
      c('Presentation versus primary adrenal failure','<p>ACTH deficiency causes secondary adrenal insufficiency: fatigue, weakness, nausea, weight loss, myalgias, hypoglycemia and hyponatremia. Aldosterone is largely preserved, so hyperkalemia, marked volume loss and hyperpigmentation are less typical than in primary disease.</p>',['acth-secondary-ai','acth-symptoms','acth-preserved-aldosterone','acth-no-hyperpigmentation'],'Which finding favors primary rather than secondary adrenal insufficiency?','Hyperpigmentation with aldosterone deficiency',['Low ACTH with low cortisol','Other pituitary deficits','Preserved potassium'],'Low cortisol, low ACTH, hyponatremia and no hyperpigmentation suggest what?','Secondary adrenal insufficiency',['Primary Addison disease','Cushing disease','Nephrogenic DI']),
      c('Diagnosis and crisis','<p>Check 8 AM cortisol with ACTH; very low cortisol with low/inappropriately normal ACTH supports central disease, while intermediate results need stimulation testing. Sudden loss from pituitary apoplexy can cause headache, visual change and shock—treat suspected crisis immediately.</p>',['acth-am-cortisol','acth-low-pair','acth-cosyntropin','apoplexy-crisis'],'What initial paired tests assess suspected ACTH deficiency?','8 AM cortisol and ACTH',['TSH and calcitonin','PTH and phosphate','Urine calcium and PTHrP'],'Severe headache, visual loss and shock occur with a pituitary mass. What is the priority?','Treat possible adrenal crisis while urgently evaluating apoplexy',['Wait for outpatient MRI only','Give levothyroxine first','Restrict all fluids']),
      c('Replacement and safety','<p>Replace glucocorticoid with hydrocortisone or equivalent, use sick-day dose escalation and emergency injection education/medical identification. Assess and treat cortisol deficiency <strong>before levothyroxine</strong> to avoid precipitating crisis.</p>',['acth-glucocorticoid-replacement','acth-sick-day','acth-emergency-education','cortisol-before-thyroid'],'What must precede thyroid replacement when ACTH deficiency is possible?','Cortisol assessment or glucocorticoid coverage',['GH suppression testing','RAIU scanning','Calcium infusion'],'A hypopituitary patient with low cortisol and low T4 needs both replacements. Which comes first?','Glucocorticoid',['Levothyroxine','GH only','Desmopressin regardless of sodium'])
    ]),
    s('13-hypogonadotropic-hypogonadism','13. Hypogonadotropic hypogonadism and manifestations','Objective 13. Slides 62–65.',[
      c('Definition and congenital disease','<p>Hypogonadotropic hypogonadism is deficient GnRH/LH/FSH signaling with low sex steroids and low/inappropriately normal gonadotropins. Congenital cases may cause micropenis, absent/delayed puberty, amenorrhea and abnormal smell (Kallmann pattern), sometimes with midline or neurologic anomalies.</p>',['hh-definition','hh-labs','hh-congenital-puberty','hh-kallmann'],'What pattern defines hypogonadotropic hypogonadism?','Low sex steroids with low/inappropriately normal LH/FSH',['Low sex steroids with very high LH/FSH','High sex steroids with high LH/FSH','Low ADH with high sodium'],'Micropenis, absent puberty and anosmia suggest what?','Congenital GnRH deficiency/Kallmann pattern',['Primary hyperparathyroidism','Acromegaly','Nephrogenic DI']),
      c('Acquired disease by sex','<p>Women may have oligomenorrhea/amenorrhea, infertility, low libido and vaginal dryness; men may have low libido/erectile function, infertility, reduced muscle/body hair and small soft testes. Both risk osteoporosis. Causes include masses, hyperprolactinemia, opioids/steroids, severe illness, undernutrition and extreme exercise.</p>',['hh-women','hh-men','hh-osteoporosis','hh-acquired-causes'],'Which consequence affects both sexes with untreated gonadotropin deficiency?','Osteoporosis',['Gigantism','Hyperpigmentation','Polycythemia in every case'],'Amenorrhea, low estradiol and low FSH occur with extreme exercise. Which level fits?','Functional hypothalamic–pituitary suppression',['Primary ovarian failure','Thyroid carcinoma','PTH excess'])
    ]),
    s('14-gonadotropin-diagnosis-treatment','14. Diagnosis and treatment of gonadotropin deficiency','Objective 14. Slides 66–68.',[
      c('Diagnostic approach','<p>Men: repeat fasting morning testosterone with LH/FSH; semen testing if fertility matters. Women: exclude pregnancy and other causes, then interpret estradiol with FSH/LH. Check prolactin, cortisol and thyroid axes; obtain pituitary MRI for other deficits, neurologic/visual findings or concerning biochemical context.</p>',['hh-male-workup','hh-female-workup','hh-other-axes','hh-mri-indications'],'What confirms central hypogonadism in a man?','Low morning testosterone with low/inappropriately normal LH',['Low testosterone with very high LH','High testosterone with low TSH','Low urine osmolality'],'Low estradiol/FSH plus visual-field loss requires what?','Pituitary MRI and full pituitary evaluation',['No imaging','Only ovarian biopsy','Water deprivation']),
      c('Treatment and fertility','<p>Replace sex steroids when appropriate: testosterone for men, estrogen with endometrial protection when uterus is present for premenopausal women. Fertility needs gonadotropins or pulsatile GnRH selected by defect: hCG/FSH for men and gonadotropin or GnRH protocols for women under reproductive specialists.</p>',['hh-sex-steroid-treatment','hh-endometrial-protection','hh-fertility-gonadotropins-gnrh'],'What changes when fertility is desired?','Use fertility-directed gonadotropin/GnRH therapy rather than sex steroid replacement alone',['Stop all hormone therapy','Use desmopressin','Use cabergoline in every case'],'A man with central hypogonadism wants fertility. Why is testosterone alone inadequate?','It does not restore intratesticular stimulation and spermatogenesis',['It always raises FSH','It causes DI','It treats prolactinoma directly'])
    ]),
    s('15-tsh-deficiency','15. TSH deficiency and central hypothyroidism','Objective 15. Slides 69–72.',[
      c('Presentation and laboratory diagnosis','<p>Central hypothyroidism can cause fatigue, cold intolerance, cramps and weight gain. The defining pattern is <strong>low free T4 with low, normal or mildly elevated biologically weak TSH</strong>; TSH alone cannot exclude it.</p>',['tsh-def-symptoms','central-hypothyroid-pattern','tsh-alone-inadequate'],'Which pattern indicates central hypothyroidism?','Low free T4 with low/inappropriately normal TSH',['Low free T4 with strongly high TSH','High free T4 with suppressed TSH','Normal free T4 with isolated high calcium'],'A symptomatic patient has low free T4 but normal TSH. What should you conclude?','Normal TSH is inappropriately normal and central disease is possible',['Thyroid function is definitely normal','This proves Graves disease','This proves DI']),
      c('Imaging, treatment, and monitoring','<p>Evaluate other pituitary axes and image the hypothalamic–pituitary region when indicated. Treat with levothyroxine only after cortisol safety is established; monitor with free T4 and symptoms because TSH is unreliable in central disease.</p>',['central-hypothyroid-mri-axes','central-lt4','central-cortisol-first','central-monitor-ft4'],'How is central hypothyroidism monitored on therapy?','Free T4 and clinical response',['TSH alone','Urine osmolality','PTHrP'],'Low cortisol and low free T4 coexist. What order is safest?','Cover cortisol first, then start levothyroxine',['Levothyroxine first','GH only','No replacement'])
    ]),
    s('16-sellar-anatomy','16. Sellar anatomy and mass manifestations','Objective 16. Slides 74–79.',[
      c('Optic chiasm and pituitary tissue','<p>The pituitary sits in the sella below the optic chiasm. Expanding masses compress pituitary tissue, then may extend upward to the chiasm, causing <strong>bitemporal hemianopia</strong>.</p>',['sella-location','mass-hypopituitarism','optic-chiasm-bitemporal'],'Which visual defect is classic for optic-chiasm compression?','Bitemporal hemianopia',['Monocular central blindness only','Homonymous hemianopia from occipital stroke','Isolated hearing loss'],'A sellar mass causes low pituitary hormones and loss of temporal visual fields. What two structures are affected?','Pituitary tissue and optic chiasm',['Thyroid and retina','Adrenal medulla and cochlea','Parathyroid and cerebellum']),
      c('Cavernous sinus and nearby structures','<p>Lateral cavernous-sinus extension can affect CN III, IV, VI and trigeminal sensory branches, producing diplopia/ophthalmoplegia or facial sensory symptoms. Headache, seizures or hydrocephalus can occur with broader expansion.</p>',['cavernous-cn','mass-diplopia-facial','mass-headache-seizure-hydrocephalus'],'Which finding suggests cavernous-sinus extension?','Diplopia from ocular motor cranial-nerve involvement',['Isolated low calcium','Bilateral ankle edema only','Glucosuria only'],'A pituitary mass produces new ophthalmoplegia. Where has it likely extended?','Cavernous sinus',['Middle ear','Thyroid follicle','Renal pelvis'])
    ]),
    s('17-adenoma-classification','17. Pituitary adenoma size and function','Objective 17. Slides 80–82.',[
      c('Micro versus macro','<p>A <strong>microadenoma is &lt;10 mm</strong>; a <strong>macroadenoma is ≥10 mm</strong>. Size predicts compression risk but does not establish hormone secretion.</p>',['micro-under10','macro-10plus','size-not-function'],'How is a 12-mm pituitary adenoma classified?','Macroadenoma',['Microadenoma','Craniopharyngioma by size alone','Meningioma by size alone'],'A 6-mm lesion produces marked prolactin excess. Which labels apply?','Functioning microadenoma',['Nonfunctioning macroadenoma','Metastasis by definition','Posterior DI']),
      c('Function and typical secretions','<p>Functioning adenomas autonomously secrete hormone; nonfunctioning tumors present through mass effect or incidental imaging. Prolactinoma is the commonest functioning adenoma. The lecture emphasizes prolactin among microadenomas and GH among functioning macroadenomas.</p>',['functioning-hypersecretion','nonfunctioning-mass','prolactinoma-common','lecture-size-secretions'],'What is the most common functioning pituitary adenoma?','Prolactinoma',['TSH adenoma','Gonadotroph hypersecretion syndrome','Posterior-pituitary adenoma'],'A large adenoma causes visual loss and low gonadotropins but no hormone-excess syndrome. How is it classified?','Nonfunctioning macroadenoma',['Functioning microprolactinoma','Central DI alone','Primary gonadal disease'])
    ]),
    s('18-adenoma-incidentaloma-workup','18. Pituitary adenoma/incidentaloma workup','Objective 18. Slide 83.',[
      c('Initial endocrine and imaging evaluation','<p>Use contrast pituitary MRI, history/exam, and labs for hypersecretion and hypopituitarism. Typical screening includes prolactin and IGF-1, cortisol-excess testing when appropriate, and target/pituitary hormone pairs. Evaluate adrenal safety promptly.</p>',['incidentaloma-mri','incidentaloma-hypersecretion','incidentaloma-hypopituitarism','incidentaloma-adrenal'],'What imaging best characterizes a sellar lesion?','Pituitary MRI with contrast',['Plain skull film only','RAIU scan','Bone scan'],'An incidental sellar lesion is found. What is required beyond measuring size?','Screen for hormone excess and deficiencies',['Assume nonfunctioning','Measure calcium only','No history or exam']),
      c('Vision, referral, and follow-up','<p>Formal visual fields are required when a lesion abuts/compresses the optic nerves or chiasm. Surgical referral is indicated for visual/neurologic compromise, chiasmal contact, apoplexy with visual symptoms, or most hypersecreting tumors except prolactinoma. Stable nonsurgical lesions need size-based MRI/endocrine follow-up. '+inc+'</p>',['incidentaloma-visual-field','incidentaloma-surgery','incidentaloma-prolactinoma-exception','incidentaloma-followup'],'When is formal visual-field testing required?','When the lesion abuts or compresses the optic apparatus',['Only when calcium is high','For every headache without imaging','Only after thyroidectomy'],'MRI shows a mass touching the chiasm despite no reported deficit. What next?','Formal visual fields and specialist referral',['Ignore until blindness','Start desmopressin','Order PTHrP'])
    ]),
    s('19-cell-types','19. Anterior pituitary cell types and functioning adenomas','Objective 19. Slides 80–86, 98, 109–111.',[
      c('Cell-to-syndrome map','<p><strong>Lactotroph → prolactin</strong> (hypogonadism/galactorrhea); <strong>somatotroph → GH</strong> (gigantism/acromegaly); <strong>corticotroph → ACTH</strong> (Cushing disease); <strong>thyrotroph → TSH</strong> (central hyperthyroidism); <strong>gonadotroph → LH/FSH</strong>, usually clinically nonfunctioning/mass effects.</p>',['cell-lactotroph','cell-somatotroph','cell-corticotroph','cell-thyrotroph','cell-gonadotroph'],'Which cell gives rise to an ACTH-secreting adenoma?','Corticotroph',['Lactotroph','Somatotroph','Posterior axon'],'High IGF-1 and acral enlargement point to which tumor cell?','Somatotroph',['Gonadotroph','Thyrotroph','Lactotroph']),
      c('Recognize functional patterns','<p>Match the biochemical pair and syndrome: PRL with reproductive suppression, GH/IGF-1 with acral growth, ACTH/cortisol with Cushing features, and high free T4 with nonsuppressed TSH in a TSH adenoma.</p>',['functional-pattern-prl','functional-pattern-gh','functional-pattern-acth','functional-pattern-tsh'],'Which pattern suggests a TSH-secreting adenoma?','High free T4 with inappropriately normal/high TSH',['Low free T4 with high TSH','Low cortisol with low ACTH','Low calcium with high PTH'],'A patient has purple striae, proximal weakness and ACTH-dependent cortisol excess. Which adenoma fits?','Corticotroph adenoma (Cushing disease)',['Lactotroph adenoma','Nonfunctioning gonadotroph only','Posterior pituitary metastasis'])
    ]),
    s('20-prolactinoma-sex-differences','20. Hyperprolactinemic adenomas in women and men','Objective 20. Slides 86–88.',[
      c('Women: earlier reproductive presentation','<p>Women often present earlier with microprolactinomas because amenorrhea/oligomenorrhea, galactorrhea, infertility and low libido are noticeable. Estrogen deficiency can reduce bone density.</p>',['prl-women-micro','prl-women-symptoms','prl-bone'],'What hallmark pattern suggests hyperprolactinemia in a woman?','Amenorrhea, galactorrhea, and infertility',['Polyuria, hypernatremia, and thirst','Hyperpigmentation and hyperkalemia','Tall stature alone'],'A woman with galactorrhea and amenorrhea has a small pituitary lesion. Which adenoma fits?','Microprolactinoma',['Nonfunctioning gonadotroph macroadenoma','Corticotroph adenoma','Meningioma']),
      c('Men: later and larger presentation','<p>Men may develop low libido, erectile dysfunction, infertility and gynecomastia. Diagnosis is often later, so macroadenomas and mass effects such as headache/visual loss are more common.</p>',['prl-men-symptoms','prl-men-macro','prl-men-mass-effect'],'Why are prolactinomas often larger at diagnosis in men?','Reproductive symptoms may be recognized later',['Prolactin cannot affect men','All male lesions grow malignantly','Men cannot develop microadenomas'],'A man has erectile dysfunction plus bitemporal field loss. Which prolactinoma pattern is concerning?','Macroprolactinoma with mass effect',['Asymptomatic microadenoma','Central DI without a mass','Primary testicular failure only'])
    ]),
    s('21-hyperprolactinemia-diagnosis-treatment','21. Hyperprolactinemia diagnosis and treatment','Objective 21. Slides 89–95.',[
      c('Confirm and exclude secondary causes','<p>Confirm prolactin under appropriate conditions and exclude pregnancy, primary hypothyroidism, renal/hepatic dysfunction and dopamine-blocking drugs. Consider macroprolactin when symptoms and result disagree; very large tumors with modest prolactin need dilution to exclude the hook effect.</p>',['prl-confirm','prl-secondary-causes','prl-medications','prl-macroprolactin','prl-hook-effect'],'Which drug class commonly raises prolactin?','Dopamine antagonists such as antipsychotics',['Thiazides through PTH','Bisphosphonates','Desmopressin'],'A patient on risperidone has elevated prolactin. What comes before diagnosing prolactinoma?','Assess medication effect and other secondary causes',['Immediate surgery','Assume cancer','Give GH']),
      c('MRI and observation','<p>Obtain pituitary MRI when persistent unexplained hyperprolactinemia suggests a sellar cause. An asymptomatic microprolactinoma without fertility goals may be observed with prolactin and clinical follow-up; larger lesions require visual/endocrine assessment.</p>',['prl-mri-indication','prl-observe-selected','prl-large-visual-assessment'],'When can a microprolactinoma sometimes be observed?','When asymptomatic and fertility is not desired',['When vision is threatened','During apoplexy with shock','When rapidly enlarging'],'Persistent unexplained prolactin elevation remains after secondary causes are excluded. What is next?','Pituitary MRI',['RAIU scan','Bone biopsy','Water deprivation']),
      c('Dopamine agonists and surgery','<p><strong>Cabergoline</strong> is usually preferred; bromocriptine is another dopamine agonist. They lower prolactin and shrink tumor. Surgery is reserved for intolerance/resistance, apoplexy or urgent/progressive visual compromise not responding promptly to medication.</p>',['prl-cabergoline','prl-bromocriptine','prl-shrink-restore-gonadal','prl-surgery-indications'],'What is usual first-line treatment for a symptomatic prolactinoma?','A dopamine agonist, usually cabergoline',['Immediate radiation in every case','Desmopressin','Levothyroxine regardless of thyroid status'],'A macroprolactinoma fails tolerated dopamine therapy and vision worsens. What next?','Transsphenoidal surgical evaluation',['Continue observation only','Start HCTZ','Give recombinant GH'])
    ]),
    s('22-gigantism-acromegaly','22. Gigantism versus acromegaly','Objective 22. Slides 98–105.',[
      c('Timing determines growth pattern','<p>GH excess <strong>before epiphyseal closure</strong> causes gigantism with rapid linear growth. After closure it causes acromegaly: bones enlarge in thickness but the patient does not become taller.</p>',['gigantism-before-closure','gigantism-linear','acromegaly-after-closure','acromegaly-not-taller'],'What distinguishes gigantism from acromegaly?','GH excess occurs before epiphyseal closure in gigantism',['Only acromegaly involves GH','Gigantism occurs only in adults','Acromegaly always increases height'],'An adult’s rings and shoes enlarge without increased height. Which diagnosis fits?','Acromegaly',['Gigantism','GH deficiency','Central DI']),
      c('Clinical features','<p>Gigantism causes extreme height plus enlarged hands/feet and coarse facial change. Acromegaly evolves slowly with macrognathia, widened tooth spacing, frontal/nasal enlargement, macroglossia, deep voice, hyperhidrosis and enlarging hands/feet.</p>',['gigantism-features','acromegaly-acral','acromegaly-facial-oral','acromegaly-sweat-voice'],'Which finding is classic for acromegaly?','Increasing ring/shoe size with jaw and facial enlargement',['Progressive short stature','Isolated galactorrhea only','Hyperpigmentation alone'],'Old photographs show gradual coarsening and widened teeth over years. What does this support?','Insidious acromegaly',['Acute DI','Congenital GH deficiency','Primary hypothyroidism only'])
    ]),
    s('23-acromegaly-complications','23. Complications of longstanding acromegaly','Objective 23. Slide 106.',[
      c('Cardiometabolic and respiratory complications','<p>Untreated disease causes hypertension, cardiomyopathy/LVH, arrhythmias, insulin resistance/diabetes and obstructive sleep apnea. These drive excess morbidity and mortality.</p>',['acro-htn-cardiomyopathy','acro-arrhythmia','acro-diabetes','acro-osa'],'Which complication is common in acromegaly?','Obstructive sleep apnea',['Central DI in every case','Permanent hypocalcemia in every case','Adrenal crisis from high ACTH'],'An acromegaly patient snores, has daytime sleepiness, HTN and glucose intolerance. What should be assessed?','Sleep apnea and cardiometabolic complications',['Only serum calcium','Only hearing','Only urine phosphate']),
      c('Musculoskeletal and neoplasia surveillance','<p>Arthropathy, carpal tunnel and spinal changes are common. Colon polyps/cancer risk is increased; screen according to acromegaly guidance and findings. Also assess thyroid enlargement/nodules and visual/pituitary deficits.</p>',['acro-arthropathy-carpal','acro-colon-risk','acro-thyroid','acro-visual-pituitary'],'Which noncardiac complication warrants attention in acromegaly?','Colon neoplasia risk',['Only kidney stones from PTH','Only cataracts from calcium','No cancer-related assessment'],'A patient with longstanding acromegaly reports hand numbness. Which complication fits?','Carpal tunnel from soft-tissue enlargement',['Laron syndrome','Primary DI','Hypoparathyroidism'])
    ]),
    s('24-acromegaly-diagnosis-treatment','24. Diagnosis and treatment of gigantism/acromegaly','Objective 24. Slides 107–108.',[
      c('IGF-1, GH suppression, and MRI','<p>Screen with age-adjusted <strong>IGF-1</strong>. If elevated, confirm failure of GH suppression after oral glucose using the laboratory’s validated assay threshold, then obtain pituitary MRI. Random GH alone is unreliable.</p>',['acro-igf1-screen','acro-ogtt-gh','acro-assay-threshold','acro-mri','acro-random-gh-poor'],'What is the best initial biochemical screen for acromegaly?','Age-adjusted IGF-1',['Random GH alone','Urine ADH','TSH alone'],'IGF-1 is high and GH fails to suppress after glucose. What is next?','Pituitary MRI',['Water deprivation','RAIU scan','Parathyroid ultrasound']),
      c('Surgery and residual disease','<p>Transsphenoidal surgery is first-line for most resectable adenomas. Persistent disease may require somatostatin receptor ligands (octreotide/lanreotide), pegvisomant, cabergoline in selected cases, repeat surgery or radiation. Monitor IGF-1 and pituitary function.</p>',['acro-surgery-first','acro-somatostatin','acro-pegvisomant-cabergoline','acro-radiation','acro-monitor'],'What is usual first-line definitive treatment for a resectable GH adenoma?','Transsphenoidal surgery',['Thyroidectomy','Desmopressin','HCTZ alone'],'IGF-1 remains high after surgery. Which option fits residual disease?','Somatostatin-directed or other acromegaly medical therapy',['No follow-up','Calcium infusion','PTH replacement'])
    ]),
    s('25-other-functioning-adenomas','25. Corticotroph, gonadotroph, and TSH-secreting adenomas','Objective 25. Slides 109–111.',[
      c('Corticotroph adenoma','<p>An ACTH-secreting corticotroph adenoma causes <strong>Cushing disease</strong>: central weight gain, proximal weakness, purple striae, easy bruising, hypertension, glucose intolerance and reproductive changes. Confirm hypercortisolism and ACTH dependence before pituitary localization.</p>',['corticotroph-cushing-disease','cushing-features','cushing-confirm-before-mri'],'What syndrome results from an ACTH-secreting pituitary adenoma?','Cushing disease',['Addison disease','Central DI','Laron syndrome'],'Purple striae, proximal weakness and ACTH-dependent cortisol excess indicate what?','Corticotroph adenoma',['Prolactinoma','Meningioma','Nephrogenic DI']),
      c('Gonadotroph adenoma','<p>Gonadotroph adenomas are usually clinically nonfunctioning. They often present as macroadenomas with headache/visual loss or hypogonadism from compression rather than a recognizable LH/FSH excess syndrome.</p>',['gonadotroph-usually-nonfunctioning','gonadotroph-mass-effect','gonadotroph-hypogonadism'],'How do gonadotroph adenomas usually present?','Mass effect or hypopituitarism',['A consistent fertility-excess syndrome','Severe hypercalcemia','Central DI without a mass'],'A macroadenoma causes visual loss and low LH/FSH without an excess syndrome. Which type is common?','Gonadotroph/nonfunctioning adenoma',['Microprolactinoma','Posterior metastasis only','TSH adenoma']),
      c('TSH-secreting adenoma','<p>A TSH adenoma causes high free T4/T3 with nonsuppressed TSH, goiter and hyperthyroid symptoms. Treat primarily with pituitary surgery; somatostatin analogs and antithyroid control may support care.</p>',['tshoma-central-hyperthyroid','tshoma-goiter','tshoma-surgery','tshoma-somatostatin-support'],'Which labs suggest a TSH adenoma?','High free T4 with inappropriately normal/high TSH',['Low T4 with high TSH','Low cortisol with low ACTH','High prolactin from pregnancy'],'Hyperthyroid symptoms, high T4, nonsuppressed TSH and a pituitary mass require what direction?','Evaluate and treat a TSH-secreting adenoma, usually surgically',['Diagnose primary Graves from TSH alone','Give desmopressin','Observe without endocrine evaluation'])
    ]),
    s('26-craniopharyngioma-meningioma','26. Craniopharyngioma and meningioma','Objective 26. Slide 112.',[
      c('Craniopharyngioma','<p>Craniopharyngiomas arise from Rathke-pouch remnants near the stalk, often with solid/cystic suprasellar components. Children often present with headache/increased pressure, visual symptoms, growth/puberty failure, hypopituitarism or DI. Management uses specialized surgery with radiation for selected residual/recurrent disease.</p>',['cranio-rathke','cranio-suprasellar-cystic','cranio-child-symptoms','cranio-hypopit-di','cranio-treatment'],'Which mass arises from Rathke-pouch remnants?','Craniopharyngioma',['Prolactinoma','Meningioma','Adrenal adenoma'],'A child has headache, growth failure, bitemporal loss and a cystic suprasellar mass. What fits?','Craniopharyngioma',['Microprolactinoma','Nephrogenic DI','Primary thyroid nodule']),
      c('Meningioma','<p>Meningiomas arise from meninges, are usually slow-growing and do not secrete pituitary hormones. They can still cause visual/cranial-nerve symptoms or pituitary dysfunction by compression.</p>',['meningioma-meninges','meningioma-slow','meningioma-nonfunctional','meningioma-compression'],'What does “nonfunctional” mean for a sellar meningioma?','It does not autonomously secrete pituitary hormone',['It cannot compress anything','It is always malignant','It cannot affect vision'],'A slow-growing nonsecretory parasellar mass compresses the optic apparatus. Which lesion is possible?','Meningioma',['Functioning lactotroph by definition','Laron syndrome','Primary DI'])
    ]),
    s('27-pituitary-metastases','27. Pituitary metastases: primaries, location, and presentation','Objective 27. Slide 113.',[
      c('Sources and posterior predilection','<p>Breast and lung are the leading primary cancers; GI, renal and other tumors can spread there. Metastases favor the posterior pituitary/stalk more than adenomas do, so new DI is a major clue.</p>',['metastasis-breast-lung','metastasis-other','metastasis-posterior-stalk','metastasis-di'],'Which primary cancers most commonly metastasize to the pituitary?','Breast and lung',['Skin and appendix only','Parathyroid only','Pituitary adenomas'],'A patient with lung cancer develops abrupt polyuria and hypernatremia. What pituitary process is concerning?','Posterior pituitary/stalk metastasis causing DI',['Microprolactinoma','Laron syndrome','Primary hyperparathyroidism']),
      c('Mass effects and evaluation','<p>Presentation may include DI, headache, visual deficits, ophthalmoplegia and anterior hormone loss. Obtain pituitary MRI and evaluate water balance, vision and all relevant pituitary axes.</p>',['metastasis-mass-effects','metastasis-anterior-loss','metastasis-workup'],'Which feature makes metastasis more likely than a typical adenoma?','New central DI in a patient with cancer',['Isolated mild prolactin elevation only','Stable 3-mm lesion','Normal thirst and urine'],'Cancer plus DI and diplopia should prompt what?','Urgent sellar imaging and pituitary-axis evaluation',['Only outpatient calcium testing','No imaging','RAIU scan'])
    ]),
    s('28-vasopressin-di-overview','28. Vasopressin/thirst pathway and DI forms/presentation','Objective 28. Slides 115–120.',[
      c('Normal osmoregulation','<p>Rising plasma osmolality activates hypothalamic thirst and ADH release. ADH acts at renal V2 receptors to retain water and concentrate urine; drinking plus renal retention lower osmolality.</p>',['avp-osmolality','avp-thirst','avp-v2-water','avp-feedback'],'What normally triggers both thirst and ADH?','Rising plasma osmolality',['Low IGF-1','High prolactin','Low calcium only'],'After water deprivation, a healthy person should do what?','Release ADH and concentrate urine',['Suppress ADH and dilute urine','Develop glucosuria','Release PTHrP']),
      c('Central versus nephrogenic DI','<p>DI is hypotonic polyuria: <strong>central DI/AVP deficiency</strong> is inadequate ADH; <strong>nephrogenic DI/AVP resistance</strong> is renal nonresponse. Both cause polyuria, nocturia and polydipsia.</p>',['di-hypotonic-polyuria','central-adh-deficiency','nephrogenic-adh-resistance','di-symptoms'],'What separates central from nephrogenic DI?','ADH deficiency versus renal resistance',['High versus low glucose','Pituitary versus thyroid TSH','High versus low calcium'],'Large volumes of dilute urine occur despite high endogenous ADH. Which form fits?','Nephrogenic DI',['Central DI','Primary adrenal insufficiency','Acromegaly']),
      c('When compensation fails','<p>With intact thirst and water access, sodium may remain high-normal. Lack of water access or impaired thirst can cause severe hypernatremia, dehydration and neurologic symptoms. Distinguish true polyuria from urinary frequency and osmotic diuresis from diabetes mellitus.</p>',['di-water-compensation','di-adipsic-hypernatremia','di-polyuria-definition','di-differential-dm-polydipsia'],'Why can untreated DI have near-normal sodium?','Thirst-driven water intake replaces losses',['The kidney concentrates normally','Glucose always falls','PTH retains water'],'An obtunded patient with DI cannot drink. What complication is urgent?','Hypernatremic dehydration',['Hypocalcemic tetany','Thyroid storm','Hyperprolactinemia'])
    ]),
    s('29-di-causes-evaluation-treatment','29. DI causes, evaluation, and treatment','Objective 29. Slides 118–125.',[
      c('Causes','<p>Central DI causes include autoimmune/idiopathic disease, craniopharyngioma or other tumors, infiltrative disease, metastasis, neurosurgery and head trauma. Nephrogenic causes include kidney disease, lithium and electrolyte disorders; primary polydipsia is a key mimic.</p>',['cdi-causes','cdi-surgery-trauma','ndi-causes','primary-polydipsia-mimic'],'Which event commonly causes transient central DI?','Transsphenoidal surgery',['Oral calcium use','Primary hypothyroidism alone','Microprolactinoma treatment with cabergoline'],'Polyuria develops after pituitary surgery. Which diagnosis must be assessed?','Central DI',['Primary hyperparathyroidism','Laron syndrome','Cushing disease']),
      c('Stepwise evaluation','<p>Confirm true hypotonic polyuria with 24-hour volume, urine osmolality, serum sodium/osmolality, glucose, kidney function and calcium/potassium. Specialist supervised water-deprivation/desmopressin testing distinguishes central DI from nephrogenic DI; stimulated copeptin testing is more accurate where available. MRI evaluates central causes; absence of the posterior bright spot supports but does not prove central DI. '+di+'</p>',['di-confirm-volume','di-serum-urine','di-exclude-solute','di-water-deprivation-supervised','di-desmopressin-response','di-copeptin','di-mri-brightspot-limited'],'How does central DI respond to desmopressin during testing?','Urine osmolality rises substantially',['Urine stays completely dilute','Glucose rises to diagnose DM','Prolactin normalizes'],'A patient has polyuria. What must be established before dynamic DI testing?','True hypotonic polyuria and exclusion of solute diuresis',['A pituitary bright spot alone','A high prolactin','A low PTH']),
      c('Treatment by type','<p>Central DI is treated with desmopressin plus access to water and education to avoid dilutional hyponatremia/overdrinking. Nephrogenic DI uses cause removal when possible, low-solute diet, thiazide and sometimes amiloride (especially lithium-related). Treat dehydration/hypernatremia carefully.</p>',['cdi-ddavp','cdi-water-access','cdi-hyponatremia-risk','ndi-remove-cause','ndi-low-solute-thiazide','ndi-amiloride-lithium'],'What is first-line hormone replacement for central DI?','Desmopressin',['Cabergoline','Hydrocortisone','Levothyroxine'],'A patient on desmopressin develops headache, confusion and low sodium after excessive water intake. What occurred?','Water intoxication from excessive antidiuresis',['Untreated nephrogenic DI','Adrenal androgen excess','GH resistance'])
    ])
  ];
})();
